float rawDepth = DepthTexture.SampleLevel(PointClamp, uv, 0);
float3 P = ReconstructViewPosition(uv, rawDepth, InvProjection);
float3 N = DecodeViewNormal(NormalTexture.SampleLevel(PointClamp, uv, 0));

float3 I = normalize(P);
float3 R = reflect(I, normalize(N));
float3 rayOrigin = P + N * normalBias;

float3 rayEnd = rayOrigin + R * maxDistance;
float4 H0 = mul(float4(rayOrigin, 1.0), Projection);
float4 H1 = mul(float4(rayEnd,    1.0), Projection);

float2 P0 = H0.xy / H0.w;
float2 P1 = H1.xy / H1.w;

// Set up perspective-correct DDA derivatives for screen position,
// reciprocal w, and the ray's view-space depth interval.
DDAState trace = SetupPerspectiveDDA(P0, P1, H0, H1, stride, jitter);
while (trace.stepCount < maxSteps && !trace.outsideViewport) {
    Advance(trace);
    if (RayIntervalOverlapsSceneDepth(trace, thickness)) break;
}

static const uint SectorCount = 32;
uint occupied = 0;
float3 indirect = 0;

for (uint step = 0; step < stepCount; ++step) {
    SampleData s = ReconstructSliceSample(step);
    uint sampleMask = SectorMask(s.frontAngle, s.backAngle, SectorCount);
    uint newMask = sampleMask & ~occupied;

    float newFraction = countbits(newMask) / float(SectorCount);
    indirect += newFraction * s.directLighting
              * saturate(dot(receiverNormal,  s.direction))
              * saturate(dot(s.normal,        -s.direction));

    occupied |= sampleMask;
}

float ambientVisibility = 1.0 - countbits(occupied) / float(SectorCount);
